mapper.select:
SELECT f.id AS cursor_id, u.id AS user_id, u.username, u.display_name, u.avatar_key, u.bio,
       EXISTS (SELECT 1 FROM follows v WHERE v.follower_id = #{viewer} AND v.followee_id = u.id) AS is_following
FROM follows f JOIN users u ON u.id = f.follower_id
WHERE f.followee_id = #{userId}
AND f.id < #{cursor}
ORDER BY f.id DESC
LIMIT #{limit}

